import { requireAdminUser } from "@/lib/server/api-auth";
import {
  handleAdminUsersCreate,
  handleAdminUsersDelete,
  handleAdminUsersUpdate,
} from "@/backend/lib-server/admin-user-route-handlers";
import { listAdminTrashedUsers, purgeExpiredAdminUserTrash } from "@/lib/server/admin-user-trash";
import { listUsersForAdmin } from "@/lib/server/registered-users";
import { enforceRateLimit, enforceTrustedOrigin, jsonWithSecurity } from "@/lib/server/security";

export const runtime = "nodejs";

export async function GET(request: Request) {
  const rateLimitError = enforceRateLimit(request, {
    scope: "admin-users-read",
    maxRequests: 120,
    windowMs: 60_000,
  });
  if (rateLimitError) {
    return rateLimitError;
  }

  const auth = await requireAdminUser(request);
  if (auth instanceof Response) {
    return auth;
  }

  await purgeExpiredAdminUserTrash();

  return jsonWithSecurity({
    ok: true,
    users: await listUsersForAdmin(),
    trashedUsers: await listAdminTrashedUsers(),
  });
}

export async function POST(request: Request) {
  const originError = enforceTrustedOrigin(request);
  if (originError) {
    return originError;
  }

  const rateLimitError = enforceRateLimit(request, {
    scope: "admin-users-create",
    maxRequests: 30,
    windowMs: 60_000,
  });
  if (rateLimitError) {
    return rateLimitError;
  }

  return handleAdminUsersCreate(request);
}

export async function PATCH(request: Request) {
  const originError = enforceTrustedOrigin(request);
  if (originError) {
    return originError;
  }

  const rateLimitError = enforceRateLimit(request, {
    scope: "admin-users-write",
    maxRequests: 40,
    windowMs: 60_000,
  });
  if (rateLimitError) {
    return rateLimitError;
  }

  return handleAdminUsersUpdate(request);
}

export async function DELETE(request: Request) {
  const originError = enforceTrustedOrigin(request);
  if (originError) {
    return originError;
  }

  const rateLimitError = enforceRateLimit(request, {
    scope: "admin-users-delete",
    maxRequests: 20,
    windowMs: 60_000,
  });
  if (rateLimitError) {
    return rateLimitError;
  }

  return handleAdminUsersDelete(request);
}
