import { randomUUID } from "node:crypto";
import { requireAdminUser } from "@/lib/server/api-auth";
import { isStrongEnoughPassword, isValidEmail, normalizeEmail } from "@/lib/server/auth-validation";
import { createDefaultCandidatePlanState, parseCandidatePlanState, serializeCandidatePlanState } from "@/lib/server/candidate-plan-state";
import { createDefaultCompanyPlanState, parseCompanyPlanState, serializeCompanyPlanState } from "@/lib/server/company-plan-state";
import {
  isTrashJustificationValid,
  listAdminTrashedUsers,
  moveAdminUserToTrash,
  purgeAdminTrashedUser,
  purgeExpiredAdminUserTrash,
  recoverAdminTrashedUser,
} from "@/lib/server/admin-user-trash";
import { prisma } from "@/lib/server/db";
import { createPasswordCredential } from "@/lib/server/password-security";
import { listUsersForAdmin } from "@/lib/server/registered-users";
import {
  resolveCompanyPlanStateId,
  resolvePlanForRole,
  resolveUserPrimaryName,
  sanitizeCredits,
  sanitizeOptionalString,
  sanitizeString,
} from "@/backend/lib-server/admin-user-utils";
import { getAllowedPlansForRole } from "@/lib/plans";
import { isSafeRouteParam, jsonWithSecurity } from "@/lib/server/security";

export async function handleAdminUsersCreate(request: Request) {
  const auth = await requireAdminUser(request);
  if (auth instanceof Response) {
    return auth;
  }

  try {
    const body = (await request.json()) as {
      role?: "candidate" | "company" | "admin";
      email?: string;
      password?: string;
      displayName?: string;
      nombre?: string;
      headline?: string;
      location?: string;
      phone?: string;
      companyName?: string;
      companyDescription?: string;
      plan?: string;
      credits?: number;
      verificationStatus?: "pending" | "verified" | "unverified";
      profileVisibility?: "public" | "private" | "recruiters_only";
    };

    const role = body.role === "candidate" || body.role === "company" || body.role === "admin" ? body.role : null;
    if (!role) {
      return jsonWithSecurity({ ok: false, message: "Rol inválido" }, { status: 400 });
    }

    const email = normalizeEmail(body.email);
    const password = body.password?.trim() ?? "";
    const nombre = sanitizeString(body.nombre, 120);
    const displayName = sanitizeString(body.displayName, 120) || resolveUserPrimaryName({
      role,
      nombre,
      displayName: body.displayName,
      companyName: body.companyName,
    }) || email;
    const headline = sanitizeString(body.headline, 160)
      || (role === "admin" ? "Administrador" : role === "company" ? "Employer Admin" : "Candidato");
    const companyName = sanitizeOptionalString(body.companyName, 160);
    const companyDescription = sanitizeOptionalString(body.companyDescription, 600);
    const location = sanitizeOptionalString(body.location, 160);
    const phone = sanitizeOptionalString(body.phone, 40);
    const credits = sanitizeCredits(body.credits);
    const plan = sanitizeString(body.plan, 40) || resolvePlanForRole(role, null);
    const verificationStatus =
      body.verificationStatus === "pending" || body.verificationStatus === "verified" || body.verificationStatus === "unverified"
        ? body.verificationStatus
        : role === "company"
          ? "pending"
          : null;
    const profileVisibility =
      body.profileVisibility === "public" || body.profileVisibility === "private" || body.profileVisibility === "recruiters_only"
        ? body.profileVisibility
        : role === "candidate"
          ? "public"
          : null;

    if (!email || !isValidEmail(email)) {
      return jsonWithSecurity({ ok: false, message: "Correo inválido" }, { status: 400 });
    }
    if (!password || !isStrongEnoughPassword(password)) {
      return jsonWithSecurity({ ok: false, message: "La contraseña no cumple la política mínima" }, { status: 400 });
    }
    if (!nombre) {
      return jsonWithSecurity({ ok: false, message: "El nombre es obligatorio" }, { status: 400 });
    }
    if (role === "company" && !companyName) {
      return jsonWithSecurity({ ok: false, message: "El nombre de la empresa es obligatorio" }, { status: 400 });
    }
    if (!getAllowedPlansForRole(role).includes(plan as never)) {
      return jsonWithSecurity({ ok: false, message: "Plan no permitido para este rol" }, { status: 400 });
    }

    const existingEmail = await prisma.user.findUnique({
      where: { email },
      select: { id: true },
    });
    if (existingEmail) {
      return jsonWithSecurity({ ok: false, message: "Ese correo ya existe" }, { status: 409 });
    }

    const userId = `${role}-${randomUUID()}`;
    const credential = await createPasswordCredential(password);
    const now = new Date();
    const candidateState = createDefaultCandidatePlanState(now);
    const companyState = createDefaultCompanyPlanState(now);

    if (credits !== null) {
      candidateState.applicationQuotaLimit = credits;
      companyState.collaboratorLimit = credits;
    }
    companyState.currentPlanId = resolveCompanyPlanStateId(plan);

    await prisma.$transaction(async (tx) => {
      await tx.user.create({
        data: {
          id: userId,
          email,
          displayName,
          role,
          plan,
        },
      });

      await tx.profile.create({
        data: {
          userId,
          nombre: role === "company" ? companyName ?? nombre : nombre,
          rol: headline,
          tipoRegistro: role === "candidate" ? "persona" : role === "company" ? "empresa" : "admin",
          ubicacion: location,
          telefono: phone,
          companyLocation: role === "company" ? location : null,
          companyName: role === "company" ? companyName : null,
          companyDescription: role === "company" ? companyDescription ?? "Empresa registrada en TalentSyncro." : null,
          verificationStatus,
          profileVisibility,
          candidatePlanStateJson: role === "candidate" ? serializeCandidatePlanState(candidateState) : null,
          companyPlanStateJson: role === "company" ? serializeCompanyPlanState(companyState) : null,
        },
      });

      await tx.credential.create({
        data: {
          userId,
          email,
          passwordHash: credential.passwordHash,
          passwordSalt: credential.passwordSalt,
        },
      });
    });

    return jsonWithSecurity({
      ok: true,
      users: await listUsersForAdmin(),
      trashedUsers: await listAdminTrashedUsers(),
    });
  } catch {
    return jsonWithSecurity({ ok: false, message: "No se pudo crear el usuario" }, { status: 500 });
  }
}

export async function handleAdminUsersUpdate(request: Request) {
  const auth = await requireAdminUser(request);
  if (auth instanceof Response) {
    return auth;
  }

  try {
    const body = (await request.json()) as {
      userId?: string;
      role?: "candidate" | "company" | "admin";
      plan?: string;
      credits?: number;
      email?: string;
      password?: string;
      displayName?: string;
      nombre?: string;
      headline?: string;
      location?: string;
      phone?: string;
      companyName?: string;
      companyDescription?: string;
      verificationStatus?: "pending" | "verified" | "unverified";
      profileVisibility?: "public" | "private" | "recruiters_only";
    };

    const userId = body.userId?.trim() ?? "";
    if (!isSafeRouteParam(userId, 120)) {
      return jsonWithSecurity({ ok: false, message: "Solicitud inválida" }, { status: 400 });
    }

    const existing = await prisma.user.findUnique({
      where: { id: userId },
      include: { profile: true },
    });
    if (!existing?.profile) {
      return jsonWithSecurity({ ok: false, message: "Usuario no encontrado" }, { status: 404 });
    }

    const existingProfile = existing.profile;
    const nextRole = body.role ?? existing.role;
    const nextPlan = body.plan?.trim() || resolvePlanForRole(nextRole, existing.plan);
    const nextCredits = sanitizeCredits(body.credits);
    const nextEmail = body.email ? normalizeEmail(body.email) : null;
    const nextPassword = body.password?.trim() ?? "";
    const nextDisplayName = sanitizeString(body.displayName, 120);
    const nextNombre = sanitizeString(body.nombre, 120);
    const nextHeadline = sanitizeString(body.headline, 160);
    const nextLocation = sanitizeOptionalString(body.location, 160);
    const nextPhone = sanitizeOptionalString(body.phone, 40);
    const nextCompanyName = sanitizeOptionalString(body.companyName, 160);
    const nextCompanyDescription = sanitizeOptionalString(body.companyDescription, 600);
    const nextVerificationStatus =
      body.verificationStatus === "pending" || body.verificationStatus === "verified" || body.verificationStatus === "unverified"
        ? body.verificationStatus
        : undefined;
    const nextProfileVisibility =
      body.profileVisibility === "public" || body.profileVisibility === "private" || body.profileVisibility === "recruiters_only"
        ? body.profileVisibility
        : undefined;

    if (body.role && auth.id === userId && body.role !== "admin") {
      return jsonWithSecurity({ ok: false, message: "No puedes quitarte el rol admin a ti mismo" }, { status: 400 });
    }
    if (body.plan) {
      const allowedPlans = getAllowedPlansForRole(nextRole);
      if (!allowedPlans.includes(body.plan as never)) {
        return jsonWithSecurity({ ok: false, message: "Plan no permitido para este rol" }, { status: 400 });
      }
    }
    if (nextEmail && !isValidEmail(nextEmail)) {
      return jsonWithSecurity({ ok: false, message: "Correo inválido" }, { status: 400 });
    }
    if (nextPassword && !isStrongEnoughPassword(nextPassword)) {
      return jsonWithSecurity({ ok: false, message: "La contraseña no cumple la política mínima" }, { status: 400 });
    }

    if (nextEmail && nextEmail !== existing.email) {
      const emailOwner = await prisma.user.findUnique({
        where: { email: nextEmail },
        select: { id: true },
      });
      if (emailOwner && emailOwner.id !== userId) {
        return jsonWithSecurity({ ok: false, message: "Ese correo ya existe" }, { status: 409 });
      }
    }

    await prisma.$transaction(async (tx) => {
      await tx.user.update({
        where: { id: userId },
        data: {
          role: nextRole,
          plan: nextPlan,
          ...(nextDisplayName ? { displayName: nextDisplayName } : {}),
          ...(nextEmail ? { email: nextEmail } : {}),
        },
      });

      const profileUpdate: Record<string, unknown> = {
        tipoRegistro: nextRole === "candidate" ? "persona" : nextRole === "company" ? "empresa" : "admin",
        nombre:
          nextNombre ||
          resolveUserPrimaryName({
            role: nextRole,
            nombre: existingProfile.nombre,
            displayName: nextDisplayName || existing.displayName,
            companyName: nextCompanyName || existingProfile.companyName,
          }) ||
          existingProfile.nombre,
        rol:
          nextHeadline ||
          existingProfile.rol ||
          (nextRole === "admin" ? "Administrador" : nextRole === "company" ? "Employer Admin" : "Candidato"),
        ubicacion: nextLocation ?? existingProfile.ubicacion,
        telefono: nextPhone ?? existingProfile.telefono,
        companyLocation:
          nextRole === "company"
            ? nextLocation ?? existingProfile.companyLocation ?? existingProfile.ubicacion
            : existingProfile.companyLocation,
        companyName:
          nextRole === "company"
            ? nextCompanyName || existingProfile.companyName || nextDisplayName || existing.displayName
            : existingProfile.companyName,
        companyDescription:
          nextRole === "company"
            ? nextCompanyDescription || existingProfile.companyDescription || "Empresa registrada en TalentSyncro."
            : existingProfile.companyDescription,
        verificationStatus: nextVerificationStatus ?? existingProfile.verificationStatus,
        profileVisibility: nextProfileVisibility ?? existingProfile.profileVisibility,
      };

      if (nextCredits !== null) {
        if (nextRole === "candidate") {
          const state = parseCandidatePlanState(existingProfile.candidatePlanStateJson, new Date());
          profileUpdate.candidatePlanStateJson = serializeCandidatePlanState({
            ...state,
            applicationQuotaLimit: nextCredits,
          });
        } else if (nextRole === "company") {
          const state = parseCompanyPlanState(existingProfile.companyPlanStateJson, new Date());
          profileUpdate.companyPlanStateJson = serializeCompanyPlanState({
            ...state,
            collaboratorLimit: nextCredits,
          });
        }
      }

      if (nextRole === "candidate" && !("candidatePlanStateJson" in profileUpdate)) {
        profileUpdate.candidatePlanStateJson = serializeCandidatePlanState(
          parseCandidatePlanState(existingProfile.candidatePlanStateJson, new Date()),
        );
      }

      if (nextRole === "company" && !("companyPlanStateJson" in profileUpdate)) {
        const state = parseCompanyPlanState(existingProfile.companyPlanStateJson, new Date());
        profileUpdate.companyPlanStateJson = serializeCompanyPlanState({
          ...state,
          currentPlanId: resolveCompanyPlanStateId(nextPlan),
        });
      }

      if (nextRole !== "candidate") {
        profileUpdate.candidatePlanStateJson = null;
      }
      if (nextRole !== "company") {
        profileUpdate.companyPlanStateJson = null;
        profileUpdate.verificationStatus = nextVerificationStatus ?? null;
      }

      await tx.profile.update({
        where: { userId },
        data: profileUpdate,
      });

      if (nextEmail || nextPassword) {
        const currentCredential = await tx.credential.findUnique({ where: { userId } });
        if (currentCredential) {
          const nextCredential = nextPassword ? await createPasswordCredential(nextPassword) : null;
          await tx.credential.update({
            where: { userId },
            data: {
              ...(nextEmail ? { email: nextEmail } : {}),
              ...(nextCredential
                ? { passwordHash: nextCredential.passwordHash, passwordSalt: nextCredential.passwordSalt }
                : {}),
            },
          });
        }

        await tx.session.updateMany({
          where: { userId, revokedAt: null },
          data: { revokedAt: new Date() },
        });
      }
    });

    return jsonWithSecurity({
      ok: true,
      users: await listUsersForAdmin(),
      trashedUsers: await listAdminTrashedUsers(),
    });
  } catch {
    return jsonWithSecurity({ ok: false, message: "No se pudo actualizar el usuario" }, { status: 500 });
  }
}

export async function handleAdminUsersDelete(request: Request) {
  const auth = await requireAdminUser(request);
  if (auth instanceof Response) {
    return auth;
  }

  try {
    await purgeExpiredAdminUserTrash();
    const body = (await request.json()) as {
      action?: "trash" | "recover" | "purge";
      userId?: string;
      trashId?: string;
      justification?: string;
      confirmed?: boolean;
      secondConfirmed?: boolean;
    };

    const action = body.action ?? "trash";
    if (action === "recover" || action === "purge") {
      const trashId = body.trashId?.trim() ?? "";
      if (!isSafeRouteParam(trashId, 120)) {
        return jsonWithSecurity({ ok: false, message: "Solicitud inválida" }, { status: 400 });
      }
      if (!body.confirmed || !body.secondConfirmed) {
        return jsonWithSecurity({ ok: false, message: "Faltan las dos confirmaciones" }, { status: 400 });
      }

      const result = action === "recover"
        ? await recoverAdminTrashedUser(trashId)
        : await purgeAdminTrashedUser(trashId);
      if (!result.ok) {
        return jsonWithSecurity({ ok: false, message: result.message }, { status: 400 });
      }

      return jsonWithSecurity({
        ok: true,
        users: await listUsersForAdmin(),
        trashedUsers: await listAdminTrashedUsers(),
      });
    }

    const userId = body.userId?.trim() ?? "";
    const justification = body.justification?.trim() ?? "";
    if (!isSafeRouteParam(userId, 120)) {
      return jsonWithSecurity({ ok: false, message: "Solicitud inválida" }, { status: 400 });
    }
    if (!body.confirmed || !body.secondConfirmed) {
      return jsonWithSecurity({ ok: false, message: "Faltan las dos confirmaciones" }, { status: 400 });
    }
    if (!isTrashJustificationValid(justification)) {
      return jsonWithSecurity({ ok: false, message: "La justificación debe tener mínimo 10 caracteres" }, { status: 400 });
    }
    if (auth.id === userId) {
      return jsonWithSecurity({ ok: false, message: "No puedes eliminar tu propia cuenta de administrador" }, { status: 400 });
    }

    const result = await moveAdminUserToTrash({
      userId,
      adminUserId: auth.id,
      justification,
    });
    if (!result.ok) {
      return jsonWithSecurity({ ok: false, message: result.message }, { status: 400 });
    }

    return jsonWithSecurity({
      ok: true,
      users: await listUsersForAdmin(),
      trashedUsers: await listAdminTrashedUsers(),
    });
  } catch {
    return jsonWithSecurity({ ok: false, message: "No se pudo eliminar el usuario" }, { status: 500 });
  }
}
