export function sanitizeString(value: unknown, maxLength = 200) {
  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
}

export function sanitizeOptionalString(value: unknown, maxLength = 200) {
  const next = sanitizeString(value, maxLength);
  return next || null;
}

export function sanitizeCredits(value: unknown) {
  return typeof value === "number" && Number.isFinite(value)
    ? Math.max(0, Math.min(10_000, Math.round(value)))
    : null;
}

export function resolveUserPrimaryName(input: {
  role: "candidate" | "company" | "admin";
  nombre?: string | null;
  displayName?: string | null;
  companyName?: string | null;
}) {
  if (input.role === "company") {
    return input.companyName?.trim() || input.nombre?.trim() || input.displayName?.trim() || "";
  }

  return input.nombre?.trim() || input.displayName?.trim() || "";
}

export function resolveCompanyPlanStateId(plan: string) {
  if (plan === "premium") {
    return "company-premium";
  }

  if (plan === "business") {
    return "company-business";
  }

  if (plan === "pro") {
    return "company-pro";
  }

  return "company-basic";
}

export function resolvePlanForRole(role: "candidate" | "company" | "admin", currentPlan?: string | null) {
  if (role === "candidate") {
    return currentPlan === "boosted" || currentPlan === "pro" ? currentPlan : "basic";
  }

  if (role === "admin") {
    return "premium";
  }

  return currentPlan === "pro" || currentPlan === "business" || currentPlan === "premium" ? currentPlan : "basic";
}
